arguments.command:
sed -i '$d' tests/price_test.sh
cat >> tests/price_test.sh <<'EOF'
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo fixed rc=$?
git stash push bin lib -q; bash scripts/verify.sh; echo old rc=$?; git stash pop -q
git status --short

